  {
    "type": "inline",
    "code": "\r\n/* =============================================================\r\n   DYNAMIC EFFECTS SCRIPT\r\n   ============================================================= */\r\n(function () {\r\n  'use strict';\r\n\t\r\n\tAOS.init({\r\n    duration: 1000,\r\n    once: true\r\n\t});\r\n  /* ---- 1. Move ticker to top of page right after DOM ready ---- */\r\n  document.addEventListener('DOMContentLoaded', function () {\r\n    var ticker = document.getElementById('dynamic-news-ticker');\r\n    if (ticker) {\r\n      ticker.style.display = '';\r\n      document.body.insertBefore(ticker, document.body.firstChild);\r\n    }\r\n  });\r\n\r\n\r\n  /* ---- 3. Animated counter (counts up when in viewport) ---- */\r\n  document.addEventListener('DOMContentLoaded', function () {\r\n    var counters = document.querySelectorAll('.count');\r\n    if (!counters.length) return;\r\n\r\n    function parseValue(txt) {\r\n      txt = txt.replace(/,/g, '').trim();\r\n      var multi = 1;\r\n      if (txt.endsWith('B')) { multi = 1e9; txt = txt.slice(0, -1); }\r\n      else if (txt.endsWith('M')) { multi = 1e6; txt = txt.slice(0, -1); }\r\n      else if (txt.endsWith('K')) { multi = 1e3; txt = txt.slice(0, -1); }\r\n      var suffix = txt.match(/[^0-9.]+$/);\r\n      suffix = suffix ? suffix[0] : '';\r\n      var num = parseFloat(txt) || 0;\r\n      return { num: num * multi, suffix: suffix, multi: multi, originalSuffix: suffix };\r\n    }\r\n\r\n    function formatBack(val, original) {\r\n      var txt = original.replace(/,/g, '').trim();\r\n      if (txt.endsWith('B') || original.includes('B')) {\r\n        return (val / 1e9).toFixed(1) + 'B';\r\n      }\r\n      if (txt.endsWith('M') || original.includes('M')) {\r\n        return (val / 1e6).toFixed(1) + 'M';\r\n      }\r\n      /* Add commas */\r\n      return Math.round(val).toLocaleString('en-IN');\r\n    }\r\n\r\n    counters.forEach(function (el) {\r\n      var original = el.textContent;\r\n      var parsed   = parseValue(original);\r\n      var started  = false;\r\n\r\n      var obs = new IntersectionObserver(function (entries) {\r\n        if (entries[0].isIntersecting && !started) {\r\n          started = true;\r\n          var start = 0;\r\n          var end   = parsed.num;\r\n          var dur   = 1800;\r\n          var startTime = null;\r\n\r\n          function step(ts) {\r\n            if (!startTime) startTime = ts;\r\n            var prog = Math.min((ts - startTime) / dur, 1);\r\n            var ease = 1 - Math.pow(1 - prog, 3);\r\n            var cur  = start + (end - start) * ease;\r\n            el.textContent = formatBack(cur, original);\r\n            if (prog < 1) requestAnimationFrame(step);\r\n            else el.textContent = original; /* restore exact original */\r\n          }\r\n          requestAnimationFrame(step);\r\n          obs.disconnect();\r\n        }\r\n      }, { threshold: 0.4 });\r\n      obs.observe(el);\r\n    });\r\n  });\r\n\r\n  /* ---- 4. Scroll-to-top button ---- */\r\n  document.addEventListener('DOMContentLoaded', function () {\r\n    var btn = document.getElementById('scroll-top-btn');\r\n    if (!btn) return;\r\n    window.addEventListener('scroll', function () {\r\n      if (window.scrollY > 400) btn.classList.add('visible');\r\n      else btn.classList.remove('visible');\r\n    });\r\n    btn.addEventListener('click', function () {\r\n      window.scrollTo({ top: 0, behavior: 'smooth' });\r\n    });\r\n  });\r\n\r\n  /* ---- 5. Subtle parallax on hero banner ---- */\r\n  document.addEventListener('DOMContentLoaded', function () {\r\n    var bannerCaption = document.querySelector('.video-banner-main-box .carousel-caption');\r\n    if (!bannerCaption) return;\r\n    window.addEventListener('scroll', function () {\r\n      var sy = window.scrollY;\r\n      if (sy < 700) {\r\n        bannerCaption.style.transform = 'translateY(' + (sy * 0.18) + 'px)';\r\n        bannerCaption.style.opacity   = 1 - sy / 600;\r\n      }\r\n    }, { passive: true });\r\n  });\r\n\r\n  /* ---- 6. Section headings fade-in on scroll ---- */\r\n  document.addEventListener('DOMContentLoaded', function () {\r\n    var headings = document.querySelectorAll('.home-heading-center, .home-heading-left-white, .world-say-heading-home');\r\n    headings.forEach(function (el) {\r\n      el.style.opacity   = '0';\r\n      el.style.transform = 'translateY(28px)';\r\n      el.style.transition = 'opacity .7s ease, transform .7s ease';\r\n\r\n      var obs = new IntersectionObserver(function (entries) {\r\n        if (entries[0].isIntersecting) {\r\n          el.style.opacity   = '1';\r\n          el.style.transform = 'translateY(0)';\r\n          obs.disconnect();\r\n        }\r\n      }, { threshold: 0.25 });\r\n      obs.observe(el);\r\n    });\r\n  });\r\n\r\n  /* ---- 7. Staggered card reveal for stand-out section ---- */\r\n  document.addEventListener('DOMContentLoaded', function () {\r\n    var cards = document.querySelectorAll('.stand-out-main-box, .dedicated-product-col-main, .leaders-home-main');\r\n    cards.forEach(function (card, i) {\r\n      card.style.opacity   = '0';\r\n      card.style.transform = 'translateY(30px)';\r\n      card.style.transition = 'opacity .55s ' + (i % 6 * 0.08) + 's ease, transform .55s ' + (i % 6 * 0.08) + 's ease, box-shadow .3s, transform .3s';\r\n\r\n      var obs = new IntersectionObserver(function (entries) {\r\n        if (entries[0].isIntersecting) {\r\n          card.style.opacity   = '1';\r\n          card.style.transform = 'translateY(0)';\r\n          obs.disconnect();\r\n        }\r\n      }, { threshold: 0.15 });\r\n      obs.observe(card);\r\n    });\r\n  });\r\n\r\n})();\r\n"
  }
